use super::*;
struct Source<'a>(&'a serde_json::Value);
impl PositionalSource for Source<'_>{fn held_len(&self)->usize{self.0["held"].as_u64().unwrap() as usize}fn target_len(&self)->Option<usize>{self.0["delta"]["len"].as_u64().map(|v|v as usize)}fn rows_len(&self)->usize{self.0["delta"]["rows"].as_array().unwrap().len()}fn row_index(&self,i:usize)->usize{self.0["delta"]["rows"][i]["index"].as_u64().unwrap() as usize}}
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn close(plan:&mut PositionalPlan){plan.begin_close();for _ in 0..10000{if plan.terminal_is_empty(){return}let d=plan.close_demand();assert_eq!(plan.close_step(Default::default()).unwrap(),Default::default());plan.close_step(grant(d)).unwrap();}panic!("positional numeric close stalled")}
#[test]
fn neutral_positional_original_source_grant_and_cancel_laws(){let corpus:serde_json::Value=serde_json::from_str(include_str!("../🧪️fixtures/🔣️.json")).unwrap();for row in corpus["cases"].as_array().unwrap(){let source=Source(row);let mut plan=PositionalPlan::new();let mut turns=0usize;loop{let d=plan.demand(&source).unwrap();for axis in 0..4{let mut short=grant(d);match axis{0=>short.maximum_items=0,1=>short.maximum_copy_bytes=127,2=>{if d.capacity_bytes==0{continue}short.maximum_capacity_bytes=d.capacity_bytes-1},_=>short.maximum_depth=0}assert_eq!(plan.advance(&source,short).unwrap().progress,Default::default());}let step=plan.advance(&source,grant(d)).unwrap();turns+=1;assert!(turns<10000);if let Some(error)=step.error{assert_eq!(error,row["error"].as_str().unwrap());break}if step.done{assert!(row.get("error").is_none());for(at,witness)in plan.origins().unwrap().iter().zip(row["origins"].as_array().unwrap()){let at=at.unwrap();assert_eq!(at.inserted,witness[0]=="row");assert_eq!(at.index,witness[1].as_u64().unwrap() as usize)}break}}close(&mut plan);for cut in[0,1,4,turns.saturating_sub(1)]{let mut cancelled=PositionalPlan::new();for _ in 0..cut{let d=cancelled.demand(&source).unwrap();let step=cancelled.advance(&source,grant(d)).unwrap();if step.done||step.error.is_some(){break}}close(&mut cancelled)}}}
